const char *filepath = "/etc/shadow";
int status;

// Check if file exists (F_OK)
status = access(filepath, F_OK);
// 0 success, -1 failure (ENOENT, EACCES)

// Check for Read permission (R_OK)
if (access(filepath, R_OK) == 0) {
    // Real user can read the file
}

// Check for Write (W_OK) and Execute (X_OK) combined
int rw_mode = W_OK | X_OK;

if (access(filepath, rw_mode) == -1) {
    // Real user lacks combined permissions
    // Check errno for specifics (EACCES, ENOENT, etc.)
}
